import marshal, types, os, glob
def collect(code, prefix=''):
    d = {}
    for c in code.co_consts:
        if isinstance(c, types.CodeType):
            d[prefix+c.co_name] = c
            d.update(collect(c, prefix+c.co_name+'.'))
    return d

for pyc in sorted(glob.glob('dateutil/__pycache__/*.pyc')) + sorted(glob.glob('dateutil/test/__pycache__/*.pyc')):
    base = os.path.basename(pyc).split('.')[0]
    cands = [os.path.join(os.path.dirname(pyc).replace('__pycache__',''), base + '.py')]
    src_path = cands[0]
    if not os.path.exists(src_path):
        print('no src for', pyc); continue
    data = open(pyc,'rb').read()
    try:
        old = marshal.loads(data[12:])
    except Exception as e:
        print('unmarshal fail', pyc, e); continue
    new = compile(open(src_path,'rb').read(), src_path, 'exec')
    o = collect(old); n = collect(new)
    diffs = []
    if set(o) != set(n):
        diffs.append('code objects differ: %s' % (sorted(set(o)^set(n)),))
    for k in sorted(set(o)&set(n)):
        co, cn = o[k], n[k]
        if co.co_code != cn.co_code: diffs.append('CODE '+k)
        if co.co_consts != cn.co_consts: diffs.append('CONSTS '+k)
        if co.co_names != cn.co_names: diffs.append('NAMES '+k)
        if co.co_varnames != cn.co_varnames: diffs.append('VARS '+k)
    print(pyc, '->', 'MATCH' if not diffs else diffs[:10])
